using Vemo.App;
using Xunit;
namespace Vemo.Core.Tests;
public sealed class WindowWorkTests {
    [Fact] public async Task ShutdownWaitsForScanAndManualExportThenRejectsNewWork(){using var work=new WindowWork();var scanRelease=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var exportRelease=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var writes=0;var scan=work.Start(async _=>{await scanRelease.Task;Interlocked.Increment(ref writes);});var export=work.Start(async _=>{await exportRelease.Task;Interlocked.Increment(ref writes);});var stop=work.StopAsync();Assert.True(work.Token.IsCancellationRequested);Assert.False(stop.IsCompleted);var rejected=work.Start(_=>{Interlocked.Increment(ref writes);return Task.CompletedTask;});await rejected;scanRelease.SetResult();await scan;Assert.False(stop.IsCompleted);exportRelease.SetResult();await Task.WhenAll(stop,export);Assert.Equal(2,writes);}
    [Fact] public async Task CancellationDrainsBackgroundBeforeStoreDisposal(){using var work=new WindowWork();var started=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var exited=false;var background=work.Start(async ct=>{started.SetResult();try{await Task.Delay(Timeout.Infinite,ct);}finally{await Task.Delay(30);exited=true;}});await started.Task;await work.StopAsync();Assert.True(exited);await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>background);}
    [Fact] public async Task FailedActionStillDrainsOtherWork(){using var work=new WindowWork();var release=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var failed=work.Start(_=>throw new InvalidOperationException("fixture"));var pending=work.Start(_=>release.Task);var stop=work.StopAsync();Assert.False(stop.IsCompleted);release.SetResult();await pending;await Assert.ThrowsAsync<InvalidOperationException>(()=>failed);await stop;}
}
